info:
cmd_seq must survive Node-RED restarts. This flow deliberately DOES NOT claim or create a persistent store. Add a named file store in your local settings.js, then restart Node-RED:

contextStorage: {
  default: "memoryOnly",
  memoryOnly: { module: "memory" },
  file: { module: "localfilesystem" }
}

The command Function explicitly reads/writes flow context with store name "file". If that store is absent, every command is BLOCKED; it never silently falls back to memory. The localfilesystem store is cached and is not a transactional or hardware-safety mechanism. Verify sequence persistence after a Node-RED restart before classroom control.

func:
function hasSeparateFileStore() {
    const key = `__course_store_probe_${Date.now()}_${Math.random().toString(16).slice(2)}`;
    const defaultMarker = `default_${key}`;
    const fileMarker = `file_${key}`;
    try {
        flow.set(key, defaultMarker);
        flow.set(key, fileMarker, "file");
        const separated = flow.get(key) === defaultMarker && flow.get(key, "file") === fileMarker;
        flow.set(key, undefined);
        flow.set(key, undefined, "file");
        return separated;
    } catch {
        try { flow.set(key, undefined); } catch {}
        try { flow.set(key, undefined, "file"); } catch {}
        return false;
    }
}

let sequenceReadiness;
if (!hasSeparateFileStore()) {
    sequenceReadiness = "BLOCKED: named persistent context store 'file' is absent or aliases the default store";
} else {
    const previous = flow.get("part4CmdSeq", "file");
    const value = previous === undefined || previous === null ? 0 : previous;
    if (!Number.isSafeInteger(value) || value < 0 || value >= 4294967295) {
        sequenceReadiness = "BLOCKED: named file context contains an invalid/exhausted cmd_seq";
    } else {
        sequenceReadiness = `READY: named file context is separate and available; next cmd_seq ${value + 1}`;
    }
}

return [
    { payload: "WAIT: subscribe to the exact retained status topic and obtain this boot_id before control" },
    { payload: sequenceReadiness },
    { payload: "命令已接受不等於實體回授；relay 必須無市電，SG90 必須獨立 5V 供電並共地" }
];

function block(text) {
    flow.set("controllerBootId", null);
    flow.set("deviceOnline", false);
    flow.set("statusReceivedAt", 0);
    flow.set("pendingCommand", null);
    node.status({ fill: "red", shape: "ring", text: "CONTROL BLOCKED" });
    return { payload: text };
}

let raw = msg.payload;
if (Buffer.isBuffer(raw)) {
    if (raw.length > 128) return block("BLOCKED: status payload exceeds 128 UTF-8 bytes");
    raw = raw.toString("utf8");
} else if (typeof raw === "string") {
    if (Buffer.byteLength(raw, "utf8") > 128) return block("BLOCKED: status payload exceeds 128 UTF-8 bytes");
} else {
    return block("BLOCKED: status payload must be UTF-8 text");
}

let p;
try {
    p = JSON.parse(raw);
} catch {
    return block("BLOCKED: status JSON parse error");
}
if (!p || typeof p !== "object" || Array.isArray(p) || typeof p.online !== "boolean") {
    return block("BLOCKED: invalid status schema");
}
if (p.online === false) {
    node.status({ fill: "red", shape: "ring", text: "DEVICE OFFLINE" });
    flow.set("controllerBootId", null);
    flow.set("deviceOnline", false);
    flow.set("statusReceivedAt", Date.now());
    flow.set("pendingCommand", null);
    return { payload: "BLOCKED: device status is offline; physical outputs are not inferred" };
}
const keys = Object.keys(p);
if (keys.length !== 2 || !Object.prototype.hasOwnProperty.call(p, "boot_id") ||
    typeof p.boot_id !== "string" || !/^[0-9a-fA-F]{8}$/.test(p.boot_id)) {
    return block("BLOCKED: online status must contain exactly online + 8-hex boot_id");
}
if (flow.get("controllerBootId") !== p.boot_id) {
    flow.set("pendingCommand", null);
}
flow.set("controllerBootId", p.boot_id);
flow.set("deviceOnline", true);
flow.set("statusReceivedAt", Date.now());
const source = msg.retain === true ? "retained snapshot" : "live status update";
node.status({ fill: "green", shape: "dot", text: `READY ${p.boot_id}` });
return { payload: `READY: ${source}; current boot_id ${p.boot_id}; status is not physical output feedback` };

initialize:
flow.set("controllerBootId", null);
flow.set("deviceOnline", false);
flow.set("statusReceivedAt", 0);
flow.set("pendingCommand", null);

func:
function invalid(text, statusText) {
    node.status({ fill: "red", shape: "ring", text: statusText });
    return { payload: `${text} | 命令已接受不等於實體回授` };
}

if (msg.retain === true) {
    return invalid("ACK INVALID: retained ACK is prohibited", "ACK RETAINED");
}

let raw = msg.payload;
if (Buffer.isBuffer(raw)) {
    if (raw.length > 256) return invalid("ACK INVALID: payload exceeds 256 UTF-8 bytes", "ACK TOO LARGE");
    raw = raw.toString("utf8");
} else if (typeof raw === "string") {
    if (Buffer.byteLength(raw, "utf8") > 256) return invalid("ACK INVALID: payload exceeds 256 UTF-8 bytes", "ACK TOO LARGE");
} else {
    return invalid("ACK INVALID: payload must be UTF-8 text", "ACK TYPE ERR");
}

let p;
try {
    p = JSON.parse(raw);
} catch {
    return invalid("ACK INVALID: JSON parse error", "ACK JSON ERR");
}
const keys = ["v", "cmd_id", "cmd_seq", "ok", "reason", "boot_id", "ts"];
const valid = p && typeof p === "object" && !Array.isArray(p) &&
    Object.keys(p).length === keys.length && keys.every((key) => Object.prototype.hasOwnProperty.call(p, key)) &&
    p.v === 1 && typeof p.cmd_id === "string" && /^[A-Za-z0-9_-]{1,24}$/.test(p.cmd_id) &&
    Number.isSafeInteger(p.cmd_seq) && p.cmd_seq >= 0 && typeof p.ok === "boolean" &&
    typeof p.reason === "string" && /^[A-Za-z0-9 _\/-]{1,32}$/.test(p.reason) &&
    typeof p.boot_id === "string" && /^[0-9a-fA-F]{8}$/.test(p.boot_id) &&
    Number.isSafeInteger(p.ts) && p.ts > 1700000000;
if (!valid) {
    return invalid("ACK INVALID: schema mismatch", "ACK SCHEMA ERR");
}
const currentBoot = flow.get("controllerBootId");
const pending = flow.get("pendingCommand");
const sameBoot = currentBoot === p.boot_id;
const matched = pending && typeof pending === "object" &&
    pending.cmd_id === p.cmd_id && pending.cmd_seq === p.cmd_seq && pending.boot_id === p.boot_id;
if (!sameBoot || !matched) {
    return invalid("ACK UNMATCHED: no matching pending cmd_id/cmd_seq/boot_id", "ACK UNMATCHED");
}
flow.set("pendingCommand", null);
node.status({ fill: p.ok ? "green" : "yellow", shape: p.ok ? "dot" : "ring", text: p.ok ? "ACK MATCHED OK" : "ACK MATCHED REJECT" });
return {
    payload: `ACK MATCHED ${p.ok ? "ACCEPTED" : "REJECTED"} | ${p.cmd_id} seq ${p.cmd_seq} | ${p.reason} | 命令已接受不等於實體回授`
};

const text = typeof msg.status?.text === "string" ? msg.status.text.trim().toLowerCase() : "unknown";
const isConnected = /(^|[.:])connected$/.test(text);
if (isConnected) {
    node.status({ fill: "green", shape: "dot", text: "MQTT CONNECTED" });
    return null;
}
flow.set("controllerBootId", null);
flow.set("deviceOnline", false);
flow.set("statusReceivedAt", 0);
flow.set("pendingCommand", null);
node.status({ fill: "red", shape: "ring", text: "CONTROL BLOCKED" });
return { payload: "BLOCKED: MQTT transport is not connected; wait for a new online status and current boot_id" };

function display(text, color = "red") {
    node.status({ fill: color, shape: color === "green" ? "dot" : "ring", text });
    return [null, { payload: text }];
}

function hasSeparateFileStore() {
    const key = `__course_store_probe_${Date.now()}_${Math.random().toString(16).slice(2)}`;
    const defaultMarker = `default_${key}`;
    const fileMarker = `file_${key}`;
    try {
        flow.set(key, defaultMarker);
        flow.set(key, fileMarker, "file");
        const separated = flow.get(key) === defaultMarker && flow.get(key, "file") === fileMarker;
        flow.set(key, undefined);
        flow.set(key, undefined, "file");
        return separated;
    } catch {
        try { flow.set(key, undefined); } catch {}
        try { flow.set(key, undefined, "file"); } catch {}
        return false;
    }
}

let req = msg.payload;
if (typeof req === "string") {
    try { req = JSON.parse(req); } catch { return display("BLOCKED: button payload parse error"); }
}
if (!req || typeof req !== "object" || Array.isArray(req) || Object.keys(req).length !== 3) {
    return display("BLOCKED: request must contain only target, value, ttl");
}
const validTraffic = req.target === "traffic" && ["red", "yellow", "green", "off"].includes(req.value);
const validRelay = req.target === "relay" && ["on", "off"].includes(req.value);
const validServo = req.target === "servo" && Number.isInteger(req.value) && req.value >= 0 && req.value <= 180;
if (!(validTraffic || validRelay || validServo) || !Number.isInteger(req.ttl) || req.ttl < 5 || req.ttl > 30) {
    return display("BLOCKED: target/value/ttl is outside the Part 3 allowlist");
}

const bootId = flow.get("controllerBootId");
if (flow.get("deviceOnline") !== true || typeof bootId !== "string" || !/^[0-9a-fA-F]{8}$/.test(bootId)) {
    return display("BLOCKED: wait for online status and current boot_id");
}
const statusAgeMs = Date.now() - Number(flow.get("statusReceivedAt") || 0);
if (!Number.isFinite(statusAgeMs) || statusAgeMs < 0) {
    return display("BLOCKED: invalid status time");
}

const now = Math.floor(Date.now() / 1000);
if (now < 1700000000) {
    return display("BLOCKED: Node-RED system time is not valid");
}
if (!hasSeparateFileStore()) {
    return display("BLOCKED: named persistent context store 'file' is absent or aliases the default store");
}

const maxCmdSeq = 4294967295;
let previous = flow.get("part4CmdSeq", "file");
if (previous === undefined || previous === null) previous = 0;
if (!Number.isSafeInteger(previous) || previous < 0 || previous >= maxCmdSeq) {
    return display("BLOCKED: persistent cmd_seq is invalid/exhausted; inspect file context");
}
flow.set("part4CmdSeq", previous + 1, "file");

const seq = previous + 1;
const command = {
    v: 1,
    cmd_id: `nr-${bootId}-${seq}`,
    cmd_seq: seq,
    boot_id: bootId,
    ts: now,
    ttl: req.ttl,
    target: req.target,
    value: req.value
};
const encoded = JSON.stringify(command);
if (Buffer.byteLength(encoded, "utf8") > 320 || command.cmd_id.length > 24) {
    return display("BLOCKED: encoded command exceeds firmware limits");
}

flow.set("pendingCommand", {
    cmd_id: command.cmd_id,
    cmd_seq: command.cmd_seq,
    boot_id: command.boot_id,
    issued_at_ms: Date.now()
});

msg.payload = encoded;
msg.topic = "REPLACE_WITH_UNIQUE_TOPIC_ROOT/cmd";
msg.qos = 1;
msg.retain = false;
node.status({ fill: "green", shape: "dot", text: `PUBLISH seq ${seq}` });
return [msg, { payload: `PUBLISH REQUESTED: ${command.target}=${command.value}, seq ${seq}, ttl ${command.ttl}s | wait for ACK; no physical feedback is implied` }];
